--- src/summary.js (added, +12 −0)
@@ -0,0 +1,12 @@
+import { taxCents } from "./tax.js";
+import { orderShippingCents } from "./shipping.js";
+
+// The numbers a checkout page shows. discountCents comes from a coupon (percentOff/amountOff difference).
+export function orderSummary(cart, { region, grams, discountCents = 0 }) {
+  const subtotal = cart.subtotalCents();
+  const discounted = subtotal - discountCents;
+  const tax = taxCents(discounted, region);
+  const shipping = orderShippingCents(discounted, grams);
+  const total = discounted + tax + shipping - discountCents;
+  return { subtotal, discount: discountCents, tax, shipping, total };
+}

